import os
import re
import subprocess
import signal
import psutil
from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/monitor/commands', methods=['POST'])
def monitor_commands():
    data = request.get_json(silent=True)
    if not data:
        return jsonify({"code": 400, "message": "Invalid JSON body"}), 400

    if 'command_regex' not in data:
        return jsonify({"code": 400, "message": "'command_regex' is required"}), 400

    command_regex = data['command_regex']
    if not isinstance(command_regex, str):
        return jsonify({"code": 400, "message": "'command_regex' must be a string"}), 400

    try:
        pattern = re.compile(command_regex, re.IGNORECASE)
    except re.error as e:
        return jsonify({"code": 400, "message": f"Invalid regular expression: {e}"}), 400

    # ps aux output format: USER PID %CPU %MEM VSZ RSS TTY      STAT START   TIME+  CMD
    # We need to capture PID and full command line (from column 11 onward)
    try:
        result = subprocess.run(
            ['ps', 'aux', '--no-header'],
            capture_output=True,
            text=True,
            timeout=10
        )
    except FileNotFoundError:
        return jsonify({"code": 500, "message": "ps command not available on this system"}), 500
    except subprocess.TimeoutExpired:
        return jsonify({"code": 500, "message": "ps command timed out"}), 500

    lines = result.stdout.strip().splitlines()
    matches = []

    for line in lines:
        parts = line.split(None, 10)  # Split into at most 11 parts, then keep the rest as command
        if len(parts) < 11:
            continue

        # ps aux fields: USER PID %CPU %MEM VSZ RSS TTY STAT START TIME+  %MEM   CMD
        # Actually: USER PID %CPU %MEM VSZ RSS TTY STAT START TIME+  CMD
        # We want PID (index 1) and CMD (index 10+)
        try:
            pid = int(parts[1])
        except ValueError:
            continue

        # Reconstruct full command line (including arguments)
        cmd = parts[10].strip() if len(parts) > 10 else ''
        # If there are more fields after 10, they are part of the command
        if len(parts) > 11:
            cmd += ' ' + ' '.join(parts[11:])

        if pattern.search(cmd):
            matches.append({
                "processId": pid,
                "processString": cmd
            })

    # Sort by PID for consistency
    matches.sort(key=lambda x: x["processId"])

    return jsonify(matches), 200


@app.errorhandler(500)
def internal_error(e):
    return jsonify({"code": 500, "message": "Internal server error"}), 500


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
